/**
 * The project's shared framework Timer. One instance keeps every lap on a
 * single timeline, so callers in different classes can read each other's marks.
 *
 * @return \rtCamp\WPFramework\Utils\Timer Shared timer.
 */
public static function timer(): \rtCamp\WPFramework\Utils\Timer {
	static $instance = null;

	if ( null === $instance ) {
		$instance = new \rtCamp\WPFramework\Utils\Timer();
	}

	return $instance;
}
